<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { Plus, RefreshCw, Search, ShieldX } from 'lucide-vue-next';import { ElMessage, ElMessageBox } from 'element-plus';import { api } from '../api';import OperationsMap from '../components/OperationsMap.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import type { PageData } from '../types';
const session=useSessionStore(),loading=ref(false),saving=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref(''),type=ref(''),level=ref(''),enterpriseId=ref(''),drawer=ref(false),detail=ref<any>(null),dialog=ref(false);const options=reactive<any>({vehicles:[],enterprises:[]});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');const canHandle=computed(()=>session.user?.permissions.includes('safety:accident:handle'));const form=reactive({vehicleId:'',operationRecordId:'',accidentType:'PROPERTY_DAMAGE',level:'MEDIUM',title:'',description:'',longitude:120.012,latitude:30.286,address:'',occurredAt:'',casualties:0,damageDescription:''});let timer:number|undefined;const typeText=(v:string)=>({COLLISION:'交通碰撞',PERSON_INJURY:'人员伤害',PROPERTY_DAMAGE:'财产损失',LOSS_OF_CONTROL:'失控事件',OTHER:'其他事故'}as any)[v]??v;const levelText=(v:string)=>({LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'重大'}as any)[v]??v;const statusText=(v:string)=>({REPORTED:'已上报',ACCEPTED:'已受理',INVESTIGATING:'调查中',RESPONSIBILITY_DETERMINED:'责任已认定',PROCESSING:'处置中',CLOSED:'已结案',ARCHIVED:'已归档'}as any)[v]??v;const fmt=(v:string)=>new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
async function loadOptions(){Object.assign(options,await api<any>('/safety/options'))}async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'20'});for(const[k,v]of Object.entries({q:q.value,status:status.value,type:type.value,level:level.value,enterpriseId:enterpriseId.value}))if(v)p.set(k,v);const data=await api<PageData<any>>(`/safety/accidents?${p}`);rows.value=data.items;total.value=data.total}catch(reason){error.value=reason instanceof Error?reason.message:'事故列表加载失败'}finally{loading.value=false}}watch([q,status,type,level,enterpriseId],()=>{page.value=1;clearTimeout(timer);timer=window.setTimeout(load,180)});watch(page,load);onMounted(()=>Promise.all([load(),loadOptions()]));
async function open(row:any){drawer.value=true;detail.value=await api<any>(`/safety/accidents/${row.id}`)}function openCreate(){Object.assign(form,{vehicleId:options.vehicles[0]?.id??'',operationRecordId:'',accidentType:'PROPERTY_DAMAGE',level:'MEDIUM',title:'',description:'',longitude:120.012,latitude:30.286,address:'',occurredAt:new Date().toISOString().slice(0,16),casualties:0,damageDescription:''});dialog.value=true}async function create(){if(!form.vehicleId||!form.title||!form.description||!form.occurredAt)return ElMessage.warning('请完整填写车辆、时间、标题和事故经过');saving.value=true;try{await api('/safety/accidents',{method:'POST',body:JSON.stringify({...form,operationRecordId:form.operationRecordId||undefined,occurredAt:new Date(form.occurredAt).toISOString()})});ElMessage.success('事故已上报并形成事故档案');dialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'上报失败')}finally{saving.value=false}}
function nextAction(row:any){return ({REPORTED:['ACCEPT','登记受理'],ACCEPTED:['INVESTIGATE','开始调查'],INVESTIGATING:['DETERMINE','责任认定'],RESPONSIBILITY_DETERMINED:['PROCESS','进入处置'],PROCESSING:['CLOSE','结案'],CLOSED:['ARCHIVE','归档']}as any)[row.status]}
async function act(row:any){const action=nextAction(row);if(!action)return;let comment='';try{comment=(await ElMessageBox.prompt('填写本阶段事实、结论或处置意见。',action[1],{inputType:'textarea',inputValidator:v=>v?.trim()?true:'请输入处理意见'})).value}catch{return}await api(`/safety/accidents/${row.id}/actions`,{method:'POST',body:JSON.stringify({action:action[0],comment})});ElMessage.success(`${action[1]}成功`);detail.value=await api<any>(`/safety/accidents/${row.id}`);await load()}
</script>
<template><PageHeader :title="isEnterprise?'事故上报':'事故管理'" :description="isEnterprise?'及时上报本企业事故并跟踪监管受理、调查和结案进度。':'从企业上报、受理调查、责任认定到结案归档，关联车辆与运行证据。'" :count="total"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreate">{{isEnterprise?'上报事故':'登记事故'}}</el-button></PageHeader><div class="table-toolbar safety-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索事故编号、标题或车辆"/><el-select v-model="type" clearable placeholder="全部事故类型"><el-option v-for="item in ['COLLISION','PERSON_INJURY','PROPERTY_DAMAGE','LOSS_OF_CONTROL','OTHER']" :key="item" :label="typeText(item)" :value="item"/></el-select><el-select v-model="level" clearable placeholder="全部等级"><el-option v-for="item in ['CRITICAL','HIGH','MEDIUM','LOW']" :key="item" :label="levelText(item)" :value="item"/></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="item in ['REPORTED','ACCEPTED','INVESTIGATING','RESPONSIBILITY_DETERMINED','PROCESSING','CLOSED','ARCHIVED']" :key="item" :label="statusText(item)" :value="item"/></el-select><el-select v-if="!isEnterprise" v-model="enterpriseId" clearable filterable placeholder="全部企业"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></div><div v-if="error" class="error-state"><strong>事故列表暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else><el-table v-loading="loading" :data="rows" row-key="id" empty-text="暂无符合条件的事故记录"><el-table-column label="事故档案" min-width="250"><template #default="{row}"><button class="table-link" @click="open(row)"><strong>{{row.title}}</strong><span>{{row.businessNo}} · {{typeText(row.accidentType)}}</span></button></template></el-table-column><el-table-column label="等级" width="82"><template #default="{row}"><span class="risk-level" :class="row.level.toLowerCase()"><i></i>{{levelText(row.level)}}</span></template></el-table-column><el-table-column label="车辆" min-width="160"><template #default="{row}"><div class="identity-cell"><strong>{{row.vehicle.name}}</strong><span>{{row.vehicle.businessNo}}</span></div></template></el-table-column><el-table-column v-if="!isEnterprise" label="所属企业" min-width="190"><template #default="{row}">{{row.enterprise.name}}</template></el-table-column><el-table-column label="发生时间 / 地点" min-width="205"><template #default="{row}"><div class="identity-cell"><strong>{{fmt(row.occurredAt)}}</strong><span>{{row.address||'位置坐标已记录'}}</span></div></template></el-table-column><el-table-column label="人员情况" width="90"><template #default="{row}">{{row.casualties?`${row.casualties} 人`:'无伤亡'}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag size="small" :type="row.status==='CLOSED'||row.status==='ARCHIVED'?'success':row.level==='CRITICAL'?'danger':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看档案</el-button></template></el-table-column></el-table><div class="pagination-row"><span>当前显示 {{rows.length}} / {{total}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next"/></div></template>
<el-drawer v-model="drawer" size="820px" destroy-on-close><template #header><div class="archive-drawer-title"><div><span>{{detail?.businessNo}}</span><h2>事故档案</h2></div><el-tag v-if="detail">{{statusText(detail.status)}}</el-tag></div></template><template v-if="detail"><div class="case-hero" :class="detail.level.toLowerCase()"><ShieldX :size="23"/><div><span>{{typeText(detail.accidentType)}} · {{levelText(detail.level)}}等级</span><strong>{{detail.title}}</strong><small>{{fmt(detail.occurredAt)}} · {{detail.source==='ENTERPRISE_REPORT'?'企业上报':'监管登记'}}</small></div></div><OperationsMap v-if="detail.operationRecord?.trackPoints?.length" mode="trajectory" :track="detail.operationRecord.trackPoints" height="360px"/><dl class="detail-grid"><div><dt>事故车辆</dt><dd>{{detail.vehicle.name}} · {{detail.vehicle.businessNo}}</dd></div><div><dt>所属企业</dt><dd>{{detail.enterprise.name}}</dd></div><div><dt>事故位置</dt><dd>{{detail.address||`${detail.longitude}, ${detail.latitude}`}}</dd></div><div><dt>人员情况</dt><dd>{{detail.casualties?`${detail.casualties} 人受伤`:'无人员伤亡'}}</dd></div><div class="detail-span-2"><dt>事故经过</dt><dd>{{detail.description}}</dd></div><div class="detail-span-2"><dt>损失情况</dt><dd>{{detail.damageDescription||'尚未登记'}}</dd></div><div class="detail-span-2"><dt>调查过程</dt><dd>{{detail.investigation||'等待调查'}}</dd></div><div class="detail-span-2"><dt>责任认定</dt><dd>{{detail.responsibility||'尚未认定'}}</dd></div><div class="detail-span-2"><dt>处置进度</dt><dd>{{detail.disposalProgress||'尚未登记'}}</dd></div></dl><div v-if="canHandle&&nextAction(detail)" class="drawer-actions"><el-button type="primary" @click="act(detail)">{{nextAction(detail)[1]}}</el-button></div></template></el-drawer>
<el-dialog v-model="dialog" :title="isEnterprise?'上报事故':'登记事故'" width="720px"><div class="form-grid"><el-form-item label="事故车辆" required><el-select v-model="form.vehicleId" filterable><el-option v-for="item in options.vehicles" :key="item.id" :label="`${item.name} · ${item.businessNo}`" :value="item.id"/></el-select></el-form-item><el-form-item label="事故时间" required><el-date-picker v-model="form.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="事故类型"><el-select v-model="form.accidentType"><el-option v-for="item in ['COLLISION','PERSON_INJURY','PROPERTY_DAMAGE','LOSS_OF_CONTROL','OTHER']" :key="item" :label="typeText(item)" :value="item"/></el-select></el-form-item><el-form-item label="事故等级"><el-select v-model="form.level"><el-option v-for="item in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="item" :label="levelText(item)" :value="item"/></el-select></el-form-item><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6" :step="0.001"/></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6" :step="0.001"/></el-form-item><el-form-item class="form-span-2" label="事故标题" required><el-input v-model.trim="form.title"/></el-form-item><el-form-item class="form-span-2" label="事故地点"><el-input v-model.trim="form.address"/></el-form-item><el-form-item class="form-span-2" label="事故经过" required><el-input v-model.trim="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="伤亡人数"><el-input-number v-model="form.casualties" :min="0" :max="999"/></el-form-item><el-form-item class="form-span-2" label="损失情况"><el-input v-model.trim="form.damageDescription" type="textarea" :rows="3"/></el-form-item></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">确认上报</el-button></template></el-dialog></template>
